<div class="box box-primary"><div class="box-header"><h3 class="box-title">Seguimiento <?php echo $encomienda['encomienda_guia']; ?></h3><div class="box-tools"><a href="<?php echo site_url('encomienda/guia/'.$encomienda['encomienda_id']); ?>" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Guía</a></div></div><div class="box-body"><div class="row"><div class="col-md-6"><h4>Datos</h4><b>Remitente:</b> <?php echo $encomienda['encomienda_remitentenombre']; ?><br><b>Destinatario:</b> <?php echo $encomienda['encomienda_destinatarionombre']; ?><br><b>Destino:</b> <?php echo $encomienda['destino_nombre']; ?><br><b>Contenido:</b> <?php echo $encomienda['encomienda_contenido']; ?></div><div class="col-md-6"><h4>Estado</h4><span class="label label-<?php echo $encomienda['encomiendaestado_color']; ?>" style="font-size:14px"><?php echo $encomienda['encomiendaestado_nombre']; ?></span><br><br><b>Total:</b> <?php echo number_format($encomienda['encomienda_total'],2); ?><br><b>Saldo:</b> <?php echo number_format($encomienda['encomienda_saldo'],2); ?><br><b>Pago:</b> <?php if(isset($encomienda['encomienda_pagadoen']) && $encomienda['encomienda_pagadoen']=='POR PAGAR AL RECOGER'){ ?><span class="label label-danger">POR PAGAR AL RECOGER</span><?php } else { ?><span class="label label-success">PAGADO</span><?php } ?><br><b>Viaje:</b> <?php echo $encomienda['viaje_id']; ?></div></div><hr><h4>Trazabilidad</h4><table class="table table-bordered"><thead><tr><th>Fecha/Hora</th><th>Estado</th><th>Movimiento</th><th>Usuario</th><th>Observación</th></tr></thead><tbody><?php foreach($movimientos as $m){ ?><tr><td><?php echo $m['movimientoencomienda_fechahora']; ?></td><td><?php echo $m['encomiendaestado_nombre']; ?></td><td><?php echo $m['movimientoencomienda_accion']; ?></td><td><?php echo $m['usuario_nombre']; ?></td><td><?php echo $m['movimientoencomienda_observacion']; ?></td></tr><?php } ?></tbody></table></div></div>
